// Voice input preprocessing and validation
const inputData = $input.item.json;

// Extract and validate voice transcript
const transcript = inputData.transcript || inputData.text || inputData.message || '';
const audioUrl = inputData.audioUrl || inputData.audio_url || '';
const userId = inputData.userId || inputData.user_id || 'anonymous';
const sessionId = inputData.sessionId || inputData.session_id || `session_${Date.now()}`;
const priority = inputData.priority || 'medium';

if (!transcript && !audioUrl) {
  throw new Error('No transcript or audio URL provided. Please provide either text or audio data.');
}

// Initialize session tracking
const sessionData = {
  sessionId,
  userId,
  transcript: transcript.trim(),
  audioUrl,
  priority,
  timestamp: new Date().toISOString(),
  status: 'processing',
  requestSource: 'voice_input'
};

// Log for debugging
console.log('Voice input processed:', sessionData);

return sessionData;

// Parse and validate orchestrator response
const aiResponse = $input.item.json;
let planData;

try {
  // Extract JSON from AI response
  const responseText = aiResponse.choices?.[0]?.message?.content || aiResponse.text || JSON.stringify(aiResponse);

  // Try to parse JSON
  if (responseText.includes('{')) {
    const jsonStart = responseText.indexOf('{');
    const jsonEnd = responseText.lastIndexOf('}') + 1;
    const jsonString = responseText.substring(jsonStart, jsonEnd);
    planData = JSON.parse(jsonString);
  } else {
    throw new Error('No JSON found in response');
  }

  // Validate required fields
  if (!planData.user_intent || !planData.tasks || !Array.isArray(planData.tasks)) {
    throw new Error('Invalid plan structure');
  }

  // Validate agent names
  const validAgents = ['ABACUS', 'GENSPARK', 'MINIMAX', 'MANUS', 'MVP'];
  planData.tasks.forEach(task => {
    if (!validAgents.includes(task.agent)) {
      console.warn(`Unknown agent: ${task.agent}, defaulting to GENSPARK`);
      task.agent = 'GENSPARK';
    }
  });

  // Add metadata
  planData.session_id = $('Preprocess Input').item.json.sessionId;
  planData.created_at = new Date().toISOString();
  planData.status = 'validated';

  return planData;

} catch (error) {
  console.error('Plan parsing error:', error.message);

  // Fallback plan for parsing errors
  return {
    user_intent: 'System error - using fallback plan',
    complexity_score: 1,
    risk_level: 'low',
    requires_approval: false,
    estimated_duration: '30 seconds',
    tasks: [{
      id: 'fallback_task',
      agent: 'GENSPARK',
      description: 'Generate a helpful response for the user query',
      priority: 'high',
      depends_on: [],
      timeout_seconds: 30,
      retry_count: 1
    }],
    coordination_notes: 'Fallback mode due to parsing error',
    session_id: $('Preprocess Input').item.json.sessionId,
    created_at: new Date().toISOString(),
    status: 'fallback',
    error: error.message
  };
}

