// Initialize execution session
const plan = $('Parse Plan').item.json;
const sessionId = plan.session_id;

// Create execution context
const executionContext = {
  session_id: sessionId,
  user_intent: plan.user_intent,
  total_tasks: plan.tasks.length,
  completed_tasks: [],
  failed_tasks: [],
  agent_results: {},
  status: 'executing',
  started_at: new Date().toISOString()
};

// Return all tasks with execution context
const tasksWithContext = plan.tasks.map((task, index) => ({
  ...task,
  index,
  status: 'pending',
  attempt: 0,
  max_retries: task.retry_count || 3,
  execution_context: executionContext
}));

return tasksWithContext;

