// Process agent results and combine all task outputs
const agentResult = $input.item.json;
const taskData = $('Route to Agent').item.json;

// Process AI response
let processedResult;
try {
  if (agentResult.choices && agentResult.choices[0]) {
    // OpenAI format
    const content = agentResult.choices[0].message.content;

    // Try to parse as JSON, fallback to text
    try {
      processedResult = JSON.parse(content);
    } catch {
      processedResult = { content: content, format: 'text' };
    }
  } else {
    processedResult = agentResult;
  }

  const result = {
    agent: taskData.agent,
    task_id: taskData.id,
    task_description: taskData.description,
    status: 'completed',
    output: processedResult,
    completed_at: new Date().toISOString(),
    execution_time: (Date.now() - new Date(taskData.execution_context.started_at).getTime()) / 1000
  };

  console.log(`${taskData.agent} agent completed:`, result);
  return result;

} catch (error) {
  console.error(`${taskData.agent} agent error:`, error.message);
  return {
    agent: taskData.agent,
    task_id: taskData.id,
    task_description: taskData.description,
    status: 'error',
    error: error.message,
    completed_at: new Date().toISOString()
  };
}

// Aggregate all agent results into final response
const allResults = $input.all();
const sessionData = $('Preprocess Input').item.json;
const planData = $('Parse Plan').item.json;

// Organize results by agent
const agentResults = {};
const completedTasks = [];
const failedTasks = [];

allResults.forEach(result => {
  const data = result.json;
  agentResults[data.agent] = data.output;

  if (data.status === 'completed') {
    completedTasks.push(data.task_id);
  } else {
    failedTasks.push(data.task_id);
  }
});

// Calculate statistics
const totalTasks = planData.tasks.length;
const successRate = Math.round((completedTasks.length / totalTasks) * 100);
const executionTime = Math.max(...allResults.map(r => r.json.execution_time || 0));

// Create comprehensive response
const finalResponse = {
  session_id: sessionData.sessionId,
  user_intent: planData.user_intent,
  request_timestamp: sessionData.timestamp,

  execution_summary: {
    status: failedTasks.length === 0 ? 'success' : 'partial_success',
    total_tasks: totalTasks,
    completed_tasks: completedTasks.length,
    failed_tasks: failedTasks.length,
    success_rate: successRate,
    execution_time_seconds: Math.round(executionTime)
  },

  agent_results: agentResults,

  task_details: planData.tasks.map(task => {
    const result = allResults.find(r => r.json.task_id === task.id);
    return {
      id: task.id,
      agent: task.agent,
      description: task.description,
      priority: task.priority,
      status: result ? result.json.status : 'not_executed',
      result: result ? result.json.output : null
    };
  }),

  coordination_notes: planData.coordination_notes,
  completed_at: new Date().toISOString(),

  // User-friendly summary
  summary: failedTasks.length === 0 
    ? `Successfully completed all ${totalTasks} tasks in ${Math.round(executionTime)} seconds.`
    : `Completed ${completedTasks.length}/${totalTasks} tasks. ${failedTasks.length} tasks failed.`,

  // Recommendations based on results
  recommendations: failedTasks.length === 0 ? [
    'All tasks completed successfully',
    'Results are ready for use',
    'System ready for next request'
  ] : [
    'Review failed tasks for potential issues',
    'Consider retrying failed operations',
    'Check task complexity and timeout settings'
  ]
};

console.log('Final orchestration result:', finalResponse);
return finalResponse;
